CREATE TABLE ship_security_compartment(security_compartment_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,ship_id bigint NOT NULL,campaign_id bigint NOT NULL,compartment_name text NOT NULL CHECK(btrim(compartment_name)<>''),airlock_connected boolean NOT NULL DEFAULT false,alarm_active boolean NOT NULL DEFAULT false,gravity_g numeric(3,1) NOT NULL DEFAULT 1.0 CHECK(gravity_g BETWEEN 0 AND 3.0),atmosphere_state text NOT NULL DEFAULT 'normal' CHECK(atmosphere_state IN('normal','vented')),concurrency_version bigint NOT NULL DEFAULT 1 CHECK(concurrency_version>0),FOREIGN KEY(ship_id,campaign_id) REFERENCES ship_ship(ship_id,campaign_id),UNIQUE(ship_id,compartment_name));
CREATE TABLE ship_security_measure_receipt(security_measure_receipt_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,security_compartment_id bigint NOT NULL REFERENCES ship_security_compartment(security_compartment_id),security_measure_code text NOT NULL REFERENCES rule_ship_security_measure(security_measure_code),initiator_actor_id bigint NOT NULL REFERENCES actor_actor(actor_id),alarm_before boolean NOT NULL,alarm_after boolean NOT NULL,gravity_before numeric(3,1) NOT NULL,gravity_after numeric(3,1) NOT NULL,atmosphere_before text NOT NULL,atmosphere_after text NOT NULL,compartment_version_before bigint NOT NULL,compartment_version_after bigint NOT NULL CHECK(compartment_version_after=compartment_version_before+1),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(security_measure_code IN('internal-alarm','artificial-gravity','vent-atmosphere')));
CREATE FUNCTION ship_finalize_security_measure() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE compartment ship_security_compartment%ROWTYPE;actor_campaign bigint;BEGIN SELECT * INTO STRICT compartment FROM ship_security_compartment WHERE security_compartment_id=NEW.security_compartment_id FOR UPDATE;SELECT campaign_id INTO STRICT actor_campaign FROM actor_actor WHERE actor_id=NEW.initiator_actor_id;
 IF actor_campaign<>compartment.campaign_id OR NEW.alarm_before<>compartment.alarm_active OR NEW.gravity_before<>compartment.gravity_g OR NEW.atmosphere_before<>compartment.atmosphere_state OR NEW.compartment_version_before<>compartment.concurrency_version THEN RAISE EXCEPTION 'Security measure receipt must snapshot its ship compartment and campaign version' USING ERRCODE='23514';END IF;
 IF NEW.security_measure_code='internal-alarm' AND NOT(NOT NEW.alarm_before AND NEW.alarm_after AND NEW.gravity_after=NEW.gravity_before AND NEW.atmosphere_after=NEW.atmosphere_before) THEN RAISE EXCEPTION 'Internal alarm activation may change only alarm state' USING ERRCODE='23514';
 ELSIF NEW.security_measure_code='artificial-gravity' AND NOT(NEW.alarm_after=NEW.alarm_before AND NEW.gravity_after BETWEEN 0 AND 3.0 AND NEW.gravity_after<>NEW.gravity_before AND NEW.atmosphere_after=NEW.atmosphere_before) THEN RAISE EXCEPTION 'Artificial gravity control must select a changed value from zero through 3G' USING ERRCODE='23514';
 ELSIF NEW.security_measure_code='vent-atmosphere' AND NOT(compartment.airlock_connected AND NEW.alarm_after=NEW.alarm_before AND NEW.gravity_after=NEW.gravity_before AND NEW.atmosphere_before='normal' AND NEW.atmosphere_after='vented') THEN RAISE EXCEPTION 'Atmosphere venting requires an airlock-connected, pressurized compartment' USING ERRCODE='23514';END IF;
 UPDATE ship_security_compartment SET alarm_active=NEW.alarm_after,gravity_g=NEW.gravity_after,atmosphere_state=NEW.atmosphere_after,concurrency_version=NEW.compartment_version_after WHERE security_compartment_id=compartment.security_compartment_id;RETURN NEW;END $$;
CREATE TRIGGER ship_security_measure_final BEFORE INSERT ON ship_security_measure_receipt FOR EACH ROW EXECUTE FUNCTION ship_finalize_security_measure();
CREATE TABLE ship_security_vent_strength_receipt(security_measure_receipt_id bigint NOT NULL REFERENCES ship_security_measure_receipt(security_measure_receipt_id),actor_id bigint NOT NULL REFERENCES actor_actor(actor_id),task_command_id bigint NOT NULL UNIQUE REFERENCES cmd_actor_task_receipt(command_id),held_on boolean NOT NULL,PRIMARY KEY(security_measure_receipt_id,actor_id));
CREATE TABLE ship_security_vent_suffocation_link(security_measure_receipt_id bigint NOT NULL REFERENCES ship_security_measure_receipt(security_measure_receipt_id),actor_id bigint NOT NULL REFERENCES actor_actor(actor_id),suffocation_episode_id bigint NOT NULL UNIQUE REFERENCES env_suffocation_episode(suffocation_episode_id),PRIMARY KEY(security_measure_receipt_id,actor_id));
CREATE FUNCTION ship_validate_vent_consequence() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE receipt ship_security_measure_receipt%ROWTYPE;compartment ship_security_compartment%ROWTYPE;actor_campaign bigint;BEGIN SELECT * INTO STRICT receipt FROM ship_security_measure_receipt WHERE security_measure_receipt_id=NEW.security_measure_receipt_id;SELECT * INTO STRICT compartment FROM ship_security_compartment WHERE security_compartment_id=receipt.security_compartment_id;SELECT campaign_id INTO STRICT actor_campaign FROM actor_actor WHERE actor_id=NEW.actor_id;IF receipt.security_measure_code<>'vent-atmosphere' OR actor_campaign<>compartment.campaign_id THEN RAISE EXCEPTION 'Venting consequence must match a vented ship compartment and actor campaign' USING ERRCODE='23514';END IF;
 IF TG_TABLE_NAME='ship_security_vent_strength_receipt' THEN IF NEW.held_on<>(SELECT succeeded FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id AND actor_id=NEW.actor_id AND characteristic_rule_id=(SELECT rule_id FROM rule_rule WHERE rule_code='characteristic.strength') AND skill_rule_id IS NULL AND difficulty_rule_id=(SELECT rule_id FROM rule_rule WHERE rule_code='difficulty.average')) THEN RAISE EXCEPTION 'Venting hang-on result must match an Average Strength check' USING ERRCODE='23514';END IF;
 ELSE IF NOT EXISTS(SELECT 1 FROM env_suffocation_episode episode JOIN rule_suffocation_profile profile USING(suffocation_profile_id) WHERE episode.suffocation_episode_id=NEW.suffocation_episode_id AND episode.actor_id=NEW.actor_id AND episode.campaign_id=compartment.campaign_id AND profile.exposure_code='utterly-airless') THEN RAISE EXCEPTION 'Venting must link the actor to utterly-airless suffocation' USING ERRCODE='23514';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER ship_vent_strength_valid BEFORE INSERT ON ship_security_vent_strength_receipt FOR EACH ROW EXECUTE FUNCTION ship_validate_vent_consequence();CREATE TRIGGER ship_vent_suffocation_valid BEFORE INSERT ON ship_security_vent_suffocation_link FOR EACH ROW EXECUTE FUNCTION ship_validate_vent_consequence();
CREATE FUNCTION ship_reject_security_measure_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Ship security measure and consequence receipts are immutable';END $$;CREATE TRIGGER ship_security_measure_immutable BEFORE UPDATE OR DELETE ON ship_security_measure_receipt FOR EACH ROW EXECUTE FUNCTION ship_reject_security_measure_mutation();CREATE TRIGGER ship_vent_strength_immutable BEFORE UPDATE OR DELETE ON ship_security_vent_strength_receipt FOR EACH ROW EXECUTE FUNCTION ship_reject_security_measure_mutation();CREATE TRIGGER ship_vent_suffocation_immutable BEFORE UPDATE OR DELETE ON ship_security_vent_suffocation_link FOR EACH ROW EXECUTE FUNCTION ship_reject_security_measure_mutation();
CREATE FUNCTION ship_guard_security_compartment() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF pg_trigger_depth()<2 THEN RAISE EXCEPTION 'Ship security compartment state changes require an immutable measure receipt' USING ERRCODE='23514';END IF;RETURN NEW;END $$;CREATE TRIGGER ship_security_compartment_guard BEFORE UPDATE OR DELETE ON ship_security_compartment FOR EACH ROW EXECUTE FUNCTION ship_guard_security_compartment();
